package com.ke.ticketsystemke.controller;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.service.WarrantyTrackerService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/volt/warranty-claims/tracker")public class WarrantyTrackerController{private final WarrantyTrackerService service;public WarrantyTrackerController(WarrantyTrackerService s){service=s;}@GetMapping public WarrantyTrackerPageResponse list(@ModelAttribute WarrantyTrackerFilter filter,Authentication auth){return service.list(filter,auth.getName());}@GetMapping("/counts")public Map<String,Long>counts(@ModelAttribute WarrantyTrackerFilter filter,Authentication auth){return service.counts(filter,auth.getName());}@GetMapping("/filter-options")public WarrantyTrackerFilterOptionsResponse options(Authentication auth){return service.options(auth.getName());}}
